// ── HOME VIEW (responsive: mobile stacked, desktop 2-col) ─────────────────────
function NewsletterPopup({ onClose }) {
  const [email,setEmail]=useState("");
  const [status,setStatus]=useState("idle");

  const handleSubmit = async () => {
    if(!email||status==="sending") return;
    setStatus("sending");
    try {
      const res = await fetch("/.netlify/functions/subscribe",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({email}),
      });
      const data = await res.json();
      if(data.success && data.already) setStatus("already"); else setStatus(data.success?"done":"error");
    } catch { setStatus("error"); }
  };

  return (
    <div style={{
      position:"fixed",inset:0,zIndex:1000,
      background:"rgba(0,0,0,0.6)",
      backdropFilter:"blur(4px)",
      display:"flex",alignItems:"center",justifyContent:"center",
      padding:"20px",
    }} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{
        background:"#fff",
        borderRadius:20,
        maxWidth:400,
        width:"100%",
        overflow:"hidden",
        boxShadow:"0 20px 60px rgba(0,0,0,0.3)",
      }}>
        {/* Top bar */}
        <div style={{background:"#0F0F0F",padding:"24px 24px 20px",position:"relative"}}>
          <button onClick={onClose} style={{position:"absolute",top:14,right:16,background:"none",border:"none",color:"rgba(255,255,255,0.5)",fontSize:20,cursor:"pointer",lineHeight:1}}>×</button>
          <p style={{fontFamily:"'Bebas Neue',sans-serif",fontSize:10,color:T.amber,letterSpacing:"0.18em",margin:"0 0 6px"}}>FREE DAILY NEWSLETTER</p>
          <h2 style={{fontFamily:"'Lora',serif",fontWeight:700,fontSize:20,color:"#fff",lineHeight:1.25,margin:0}}>The AI shift in your inbox every morning.</h2>
        </div>
        {/* Body */}
        <div style={{padding:"20px 24px 24px"}}>
          <p style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:13,color:"#4A4A4A",lineHeight:1.6,margin:"0 0 16px"}}>What moved in AI, who's making money from it, and what you should do next. Free. Every day.</p>
          {(status==="done"||status==="already") ? (
            <div style={{background:status==="already"?"#FFFBF0":"#F0FDF4",border:`1px solid ${status==="already"?"#F5A623":"#16A34A"}`,borderRadius:12,padding:"16px",textAlign:"center"}}>
              <p style={{fontFamily:"'Lora',serif",fontWeight:700,fontSize:16,color:"#0F0F0F",margin:"0 0 4px"}}>{status==="already"?"You're already subscribed.":"You're in."}</p>
              <p style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:12,color:"#6B6B6B",margin:0}}>{status==="already"?"We'll see you every morning.":"First issue tomorrow morning."}</p>
            </div>
          ) : (
            <div style={{display:"flex",flexDirection:"column",gap:8}}>
              <input type="email" placeholder="your@email.com" value={email}
                onChange={e=>setEmail(e.target.value)}
                onKeyDown={e=>e.key==="Enter"&&handleSubmit()}
                style={{width:"100%",background:"#F8F8F6",border:"1px solid #E4E4E0",borderRadius:24,color:"#0F0F0F",padding:"12px 16px",fontFamily:"'IBM Plex Sans',sans-serif",fontSize:13,outline:"none",boxSizing:"border-box"}}/>
              <button onClick={handleSubmit} disabled={!email||status==="sending"}
                style={{width:"100%",background:email?"#0F0F0F":"#E4E4E0",border:"none",borderRadius:24,color:email?"#fff":"#9B9B9B",padding:"12px 0",fontFamily:"'IBM Plex Sans',sans-serif",fontSize:13,cursor:email?"pointer":"not-allowed",fontWeight:600,transition:"all 0.2s"}}>
                {status==="sending"?"Subscribing...":"Get the daily shift →"}
              </button>
              {status==="error"&&<p style={{textAlign:"center",fontFamily:"'IBM Plex Sans',sans-serif",fontSize:11,color:"#E8001C",margin:0}}>Something went wrong. Try again.</p>}
              <button onClick={onClose} style={{background:"none",border:"none",color:"#9B9B9B",fontFamily:"'IBM Plex Sans',sans-serif",fontSize:11,cursor:"pointer",padding:"4px 0"}}>No thanks</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

