// ── STORY SLIDESHOW (consistent height, YouTube videos, nav arrows) ─────────────
function StorySlideshow({ articles, onSelect, slideshowTopic }) {
  const [slideIdx, setSlideIdx] = useState(0);
  const [slideH, setSlideH] = useState(460);
  const touchStartX = useRef(null);

  useEffect(()=>{
    const update = () => setSlideH(window.innerWidth < 640 ? 300 : 460);
    update();
    window.addEventListener('resize', update);
    return ()=>window.removeEventListener('resize', update);
  },[]);

  // Reset slide index when topic changes
  useEffect(()=>{ setSlideIdx(0); },[slideshowTopic]);

  // Primary source: slideshow-topic.json (always has videos, always consistent)
  // Fallback: find a visual article with videos in today's feed
  const topicFromFeed = articles.find(a => a.visual === true && a.videos && a.videos.length > 0) ||
                        articles.find(a => a.videos && a.videos.length > 0);

  const topic = slideshowTopic || topicFromFeed;
  if (!topic || !topic.videos || topic.videos.length === 0) return null;

  const videos = topic.videos;
  const slides = [{ type:'hook' }, ...videos.map(v=>({ type:'video', ...v }))];
  const total = slides.length;
  const slide = slides[slideIdx];
  const goNext = () => { if(slideIdx<total-1) setSlideIdx(s=>s+1); };
  const goPrev = () => { if(slideIdx>0) setSlideIdx(s=>s-1); };

  const TITLE_H = 52;
  const videoH = slideH - TITLE_H;
  const videoW = Math.round(videoH * 16/9);



  return (
    <div style={{background:"#0F0F0F",userSelect:"none"}}
      onTouchStart={e=>{touchStartX.current=e.touches[0].clientX;}}
      onTouchEnd={e=>{
        if(touchStartX.current===null) return;
        const dx=e.changedTouches[0].clientX-touchStartX.current;
        if(dx<-40) goNext(); else if(dx>40) goPrev();
        touchStartX.current=null;
      }}>

      {/* Fixed-height slide container */}
      <div style={{height:slideH,position:"relative",overflow:"hidden"}}>

        {slide.type==="hook"&&(
          <>
            <NewsImg src={topic.img} style={{width:"100%",height:"100%",objectFit:"cover",opacity:0.4}}/>
            <div style={{position:"absolute",inset:0,background:"linear-gradient(to bottom,rgba(0,0,0,0.1) 0%,rgba(0,0,0,0.88) 100%)"}}/>
            <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",justifyContent:"flex-end",padding:"20px 20px 24px 20px"}}>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
                <CatBadge cat={topic.cat}/>
                <span style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:11,color:"rgba(255,255,255,0.55)"}}>{topic.source}</span>
              </div>
              <p style={{fontFamily:"'Bebas Neue',sans-serif",fontSize:slideH<350?26:34,color:"#fff",lineHeight:1.08,margin:"0 0 10px",letterSpacing:"0.02em"}}>{topic.hook || topic.headline}</p>
              <p style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:12,color:T.amber,fontWeight:700,margin:0,letterSpacing:"0.1em",textTransform:"uppercase"}}>
                {`${videos.length} videos — tap arrow or swipe`}
              </p>
            </div>
          </>
        )}

        {slide.type==="video"&&(
          <div style={{height:"100%",display:"flex",flexDirection:"column",background:"#000"}}>
            <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden"}}>
              <iframe
                src={`https://www.youtube.com/embed/${slide.videoId}?rel=0&modestbranding=1`}
                width={Math.min(videoW, 9999)}
                height={videoH}
                style={{border:"none",maxWidth:"100%",display:"block"}}
                allowFullScreen allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              />
            </div>
            <div style={{height:TITLE_H,background:"#111",padding:"0 56px 0 16px",display:"flex",flexDirection:"column",justifyContent:"center",flexShrink:0}}>
              <p style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:12,fontWeight:600,color:"#fff",margin:"0 0 2px",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{slide.title}</p>
              <p style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:10,color:"rgba(255,255,255,0.4)",margin:0}}>{slide.channel}</p>
            </div>
          </div>
        )}

      </div>

      {/* Arrows + dots row */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:12,padding:"8px 0",background:"#0F0F0F"}}>
        <button onClick={goPrev} disabled={slideIdx===0}
          style={{background:"none",border:"none",color:slideIdx===0?"rgba(255,255,255,0.2)":"rgba(255,255,255,0.8)",
            fontSize:22,cursor:slideIdx===0?"default":"pointer",padding:"0 4px",lineHeight:1}}>‹</button>
        {slides.map((_,i)=>(
          <div key={i} onClick={()=>setSlideIdx(i)}
            style={{width:i===slideIdx?16:5,height:5,borderRadius:3,
              background:i===slideIdx?"#fff":"rgba(255,255,255,0.25)",
              transition:"all 0.2s",cursor:"pointer"}}/>
        ))}
        <button onClick={goNext} disabled={slideIdx===total-1}
          style={{background:"none",border:"none",color:slideIdx===total-1?"rgba(255,255,255,0.2)":"rgba(255,255,255,0.8)",
            fontSize:22,cursor:slideIdx===total-1?"default":"pointer",padding:"0 4px",lineHeight:1}}>›</button>
      </div>
    </div>
  );
}



function HomeView({ articles, date, cat, setCat, page, setPage, onSelect, onNav, weeklyArticles, lastWeekArticles, slideshowTopic }) {
  const feed = (cat==="All" ? articles.filter(a=>!a.feat) : articles.filter(a=>a.cat===cat));
  const shown = feed.slice(0,(page+1)*6);
  const more = (page+1)*6 < feed.length;

  return (
    <div>
      <Marquee/>
      <StorySlideshow articles={articles} onSelect={onSelect} slideshowTopic={slideshowTopic}/>
      <div style={{background:T.bg,maxWidth:1200,margin:"0 auto"}}>
        <div style={{height:1,background:T.light,margin:`0 ${INSET}px`}}/>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:`16px ${INSET}px 6px`}}>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <div style={{width:3,height:16,background:T.red,borderRadius:2}}/>
            <span style={{fontFamily:"'Lora',serif",fontWeight:700,fontSize:16,color:T.ink}}>Stories Today</span>
          </div>
          <span style={{fontFamily:"'IBM Plex Sans',sans-serif",fontSize:11,color:T.mid}}>{date}</span>
        </div>
        <CategoryPills cat={cat} setCat={c=>{setCat(c);setPage(0);}}/>

        {/* Responsive grid: 1-col mobile, 2-col desktop */}
        <div className="story-grid">
          {shown.map((s,i)=>(
            <div key={s.id} style={{borderBottom:T.border}}>
              <StoryCard story={s} onSelect={onSelect}/>
            </div>
          ))}
        </div>

        <div style={{padding:`16px ${INSET}px`}}>
          {more
            ?<button onClick={()=>setPage(p=>p+1)} style={{width:"100%",background:T.card,border:T.border,borderRadius:24,padding:"12px 0",fontFamily:"'IBM Plex Sans',sans-serif",fontSize:13,color:T.ink,cursor:"pointer",fontWeight:500}}>Load more stories</button>
            :<p style={{textAlign:"center",fontFamily:"'IBM Plex Sans',sans-serif",fontSize:12,color:T.mid,margin:0}}>You're all caught up · Check back tomorrow</p>
          }
          <div style={{height:1,background:T.light,margin:`16px 0 0`}}/>
        </div>
      </div>
      <APIPriceMarquee/>
      <BriefStrip onNav={onNav} onSelect={onSelect} weeklyArticles={weeklyArticles}/>
      <LastWeekSection lastWeekArticles={lastWeekArticles} onSelect={onSelect} onNav={onNav}/>
      <LiveSection/>
      <LearnTeaser onNav={onNav}/>
      <ResourcesTeaser onNav={onNav}/>
      <NewsletterCTA/>
    </div>
  );
}

